#define PROGRESS_BAR_HEIGHT 5
#define PROGRESS_BAR_WIDTH 300
#define PROGRESS_BAR_SLICE (PROGRESS_BAR_WIDTH/100)
#define PROGRESS_BAR_COLOUR 0xFFFFFFFF
#define PROGRESS_BAR_X (vbe_info.width/2)-150
#define PROGRESS_BAR_Y (vbe_info.height/2)+100

int progress_percent = 0;

void splash_render(int offset_x,int offset_y) {
    unsigned int x, y;
    unsigned int pixel_value;
    for (y = 0; y < (gimp_image.height); y++) {
        for (x = 0; x < (gimp_image.width); x++) {
            unsigned int index = (y * gimp_image.width + x) * gimp_image.bytes_per_pixel;
            unsigned char r = gimp_image.pixel_data[index + 0];
            unsigned char g = gimp_image.pixel_data[index + 1];
            unsigned char b = gimp_image.pixel_data[index + 2];
            pixel_value = (0xFF << 24) | (r << 16) | (g << 8) | b;
            vbe_fast_putpixel(x+offset_x,y+offset_y,pixel_value);
        }
    }
    vbe_flip();
}

void splash_progress_bar(int progress) {
    progress_percent += progress;

    vbe_fillrect(PROGRESS_BAR_X, PROGRESS_BAR_Y, PROGRESS_BAR_SLICE * progress_percent, PROGRESS_BAR_HEIGHT, PROGRESS_BAR_COLOUR);
    vbe_flip();
}
